import{jsonResolver}from"../utils/_utils.js";const getEntireRecitersService=async()=>{return await jsonResolver("EntireReciters")};const getSpesificReciterService=async reciterId=>{const reciters=await getEntireRecitersService();const spesificReciter=new Map(reciters.map(reciter=>[reciter.id,reciter]));return spesificReciter.get(reciterId)};export{getEntireRecitersService,getSpesificReciterService};